    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    last_m, last_o = history[-1]

    total_oppD = 0
    for pair in history:
        if pair[1] == 'D':
            total_oppD += 1

    streak_oppD = 0
    i = n - 1
    while i >= 0 and history[i][1] == 'D':
        streak_oppD += 1
        i -= 1

    oppD6 = 0
    oppD8 = 0
    oppD10 = 0
    oppD20 = 0
    cd8 = 0
    cd20 = 0
    dc6 = 0

    for pos in range(1, 21):
