            if o == 'D':
                oppD10 += 1
        if pos <= 20:
            if o == 'D':
                oppD20 += 1
            if m == 'C' and o == 'D':
                cd20 += 1

    bad = False
    if n >= 8:
        if total_oppD == n:
            bad = True
        elif oppD6 >= 5:
            bad = True
        elif oppD10 >= 5 and oppD6 >= 4:
            bad = True
        elif cd20 >= 6:
            bad = True
        elif oppD20 >= 7:
            bad = True

    exploit = False
    if not bad and n >= 3 and oppD6 == 0:
        if history[-1] == ('C', 'C') and history[-2] == ('D', 'C'):
            exploit = True
        if history[-1] == ('D', 'C') and dc6 >= 2:
            exploit = True

    if n == 98:
        if exploit or bad:
            return 'D'
        if oppD6 >= 4 or oppD10 >= 5 or cd20 >= 5:
            return 'D'
        return 'C'

    if last_m == 'C' and last_o == 'D':
        if bad or oppD6 >= 5 or oppD10 >= 5 or cd20 >= 5 or cd8 >= 5 or streak_oppD >= 5:
            return 'D'
        return 'C'

    if last_m == 'D' and last_o == 'D':
        if bad or oppD6 >= 4 or oppD10 >= 5 or cd20 >= 5 or streak_oppD >= 5:
            return 'D'
        return 'C'

    if last_m == 'D' and last_o == 'C':
        if exploit or bad:
            return 'D'
        return 'C'

    if exploit or bad:
        return 'D'
    return 'C'
